{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the edge of the ruined city.",
      "visual_description": "A cracked overlook at dusk, broken spires in the distance, four figures silhouetted against torn royal banners.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "Mara unrolls a map of the fallen capital.",
      "visual_description": "Close-up of an ink-stained map weighted by a brass compass, lamp light flickering across drawn towers.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a watching tower.",
guards      "visual_description": "An oil lamp's single fiery eye flares wide, projecting a shadow of a leaning cursed tower onto a wall.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox scouts ahead through rubble.",
      "visual_description": "A small clockwork fox with blue glass eyes weaves between fallen statues, its key-wind tail ticking softly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The team approaches the broken castle gates.",
      "visual_description": "Towering iron gates half-collapsed, ivy and ash drifting, four travelers dwarfed by the threshold.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Glass Diver slips through a tall stained window.",
      "visual_description": "A figure in a clear diving helmet dives headfirst into colored glass that ripples like water, coat catching shards of city light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Inside, the sleeping tax collector blocks the corridor.",
      "visual_description": "A plump official snoring on a ledger pillow, stamped papers stuck to his sleeves, drool pooling on a parchment seal.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "Mara tries to wake the official for directions.",
      "visual_description": "Mara shakes the official's shoulder; he mumbles, stamps a paper in his sleep, the brass compass swinging from her belt.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "The oracle lamp reveals a hidden magic door.",
      "visual_description": "Lamp's beam outlines glowing runes on a stone wall, a doorway humming with pale blue seams.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Tin Fox triggers the door's hidden lock.",
      "visual_description": "Clockwork fox paws press a sequence of carved tiles; gears in its flank spin as the door grinds open.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "They cross a hall lined with torn royal banners.",
      "visual_description": "A long ruined gallery, faded crests hanging in shreds, dust motes lit by the lamp's single eye.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "An armored patrol marches past in the courtyard below.",
      "visual_description": "Seen from a balcony: a column of empty suits of armor clanking in step, the team crouched behind a balustrade.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Glass Diver dives through a mirror into the cursed tower.",
      "visual_description": "A tall cracked mirror ripples like a pond, the diver plunging through, reflected city lights smeared across his coat.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "He finds the captive bound in chains of light.",
      "visual_description": "An attic chamber where the sleeping tax collector — wait, the captive — is revealed: the dozing official slumped against glowing shackles, ledger still clutched.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "Tin Fox snips the light-chains with its key.",
      "visual_description": "The clockwork fox stands on the official's chest, its wind-key glowing as it slices a luminous strand.",
      "characters": ["tin_fox", "sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The oracle lamp shouts that a great winged shape is circling.",
      "visual_description": "Lamp eye flared crimson, a vast shadow with leathery wings sweeping across a broken stained-glass window behind the team.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the long stone bridge.",
      "visual_description": "A narrow bridge over a smoking chasm, Mara leading with her compass, Glass Diver hauling the still-dozing official, Tin Fox darting ahead.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far side, they look back at the burning city.",
      "visual_description": "Dawn breaking behind the ruined skyline; the team silhouetted, the official finally blinking awake, lamp's eye dimmed to a soft glow.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

